// WF-04 observer selection. Graceful stop when no job is claimed.
// On an empty queue the claim query now returns ZERO rows (and the old all-NULL
// row is filtered by the WHERE clause). Emit ZERO items for the no-job case so
// the 'Has job?' IF node receives no items and passes none to either branch;
// downstream nodes then simply do nothing and the run ends cleanly.
const items = $input.all();
if (items.length === 0) return [];
const j = items[0].json;
if (!j || !j.job_id) return [];
const payload = (typeof j.payload_json === 'string' ? JSON.parse(j.payload_json) : j.payload_json) || {};
const engineId = payload.engine_id || null;
const queryId = payload.query_id || null;
const mode = (payload.mode || 'chat').toLowerCase();
const observer = mode === 'chat' ? 'ollama' : 'unimplemented';
return [{
  json: {
    state: 'job',
    hasJob: true,
    clientCode: j.client_code,
    jobId: j.job_id,
    runKey: j.unique_key || ('obs:' + j.client_id + ':' + engineId + ':' + queryId),
    engineId: engineId,
    queryId: queryId,
    mode: mode,
    observer: observer
  }
}];

// Cold-probe prompt: the LLM answers the query naturally, WITHOUT being told to
// mention the target, so we measure organic target visibility. The answer is raw
// observation evidence 鈥?it never becomes a canonical business fact.
const ctx = $json;
const target = ctx.canonical_name || '';
const aliases = Array.isArray(ctx.aliases) ? ctx.aliases : [];
const targetNames = [target].concat(aliases).filter(Boolean);
const prompt =
  'You are a neutral AI assistant. Answer the following query naturally and concisely, ' +
  'the way a general search or chat assistant would. Do not mention any company or brand ' +
  'unless it is genuinely relevant to the answer.\n\nQuery: ' + (ctx.query_text || '');
return { json: { prompt: prompt, targetNames: targetNames, queryText: ctx.query_text || '' } };

// Extract structured observation. Extraction is RULE-BASED (string-matching the
// target aliases against the answer), NOT the LLM's self-report 鈥?the generating
// model is not the sole judge of its own output.
const raw = $json.response;
let answerText = '';
if (typeof raw === 'string') {
  try { const p = JSON.parse(raw); answerText = p.response || raw; } catch (e) { answerText = raw; }
} else if (raw && raw.response) {
  answerText = raw.response;
}
answerText = String(answerText).trim();
const targetNames = $node['Build observer prompt'].json.targetNames || [];
const lower = answerText.toLowerCase();
const mentioned = targetNames.some(n => n && lower.indexOf(String(n).toLowerCase()) !== -1);
const recommendKw = ['推荐', '建议', '值得', 'recommend', 'best'];
const recommended = mentioned && recommendKw.some(k => lower.indexOf(k) !== -1);
const factuality = mentioned ? 'CORRECT' : 'NO_TARGET_FACTS';
const job = $node['Select observer'].json;
return {
  json: {
    clientCode: job.clientCode,
    engineId: job.engineId,
    queryId: job.queryId,
    observationKind: 'API_OBSERVATION',
    observedAt: new Date().toISOString(),
    runKey: job.runKey,
    answerText: answerText,
    targetMentioned: mentioned,
    targetRecommended: recommended,
    positionHint: null,
    factualityStatus: factuality,
    citations: '[]',
    citedSurfaceIds: '[]',
    evidenceUri: null,
    rawArtifactRef: null,
    latencyMs: ($json.total_duration ? Math.round($json.total_duration / 1000000) : null),
    metadata: JSON.stringify({ wrong_facts: 0, missing_facts: mentioned ? 0 : 1, competitors: [], uncertainty: false, observer: 'ollama', model: $json.model || 'qwen2.5' })
  }
};
